 private final class WorkspacePanes extends LinearLayout {
  private final LinearLayout controls,examples;private Boolean horizontal;
  WorkspacePanes(LinearLayout first,LinearLayout second){super(OneActivity.this);controls=first;examples=second;setGravity(Gravity.TOP);addView(controls);addView(examples);}
  @Override protected void onMeasure(int widthSpec,int heightSpec){float density=getResources().getDisplayMetrics().density;int width=Math.round(Math.max(0,MeasureSpec.getSize(widthSpec)-getPaddingLeft()-getPaddingRight())/density);int height=root.getHeight()>0?Math.round((root.getHeight()-root.getPaddingTop()-root.getPaddingBottom())/density):getResources().getConfiguration().screenHeightDp;boolean split=OneLayoutPolicy.workspaceSplitContent(width,height,getResources().getConfiguration().fontScale);if(horizontal==null||horizontal!=split){horizontal=split;setOrientation(split?HORIZONTAL:VERTICAL);controls.setLayoutParams(new LinearLayout.LayoutParams(split?0:LayoutParams.MATCH_PARENT,LayoutParams.WRAP_CONTENT,split?4:0));LinearLayout.LayoutParams second=new LinearLayout.LayoutParams(split?0:LayoutParams.MATCH_PARENT,LayoutParams.WRAP_CONTENT,split?6:0);second.leftMargin=split?Ui.dp(OneActivity.this,16):0;examples.setLayoutParams(second);}super.onMeasure(widthSpec,heightSpec);}
 }
 private final class ResponsiveCards extends ViewGroup {
  private final ArrayList<Integer> heights=new ArrayList<>();private int columns=1,childWidth;private final int gap=Ui.dp(OneActivity.this,12);
  ResponsiveCards(){super(OneActivity.this);}
  @Override protected LayoutParams generateDefaultLayoutParams(){return new LayoutParams(LayoutParams.MATCH_PARENT,LayoutParams.WRAP_CONTENT);}
  @Override protected void onMeasure(int widthSpec,int heightSpec){int width=MeasureSpec.getSize(widthSpec),inside=Math.max(1,width-getPaddingLeft()-getPaddingRight());columns=OneLayoutPolicy.modelColumns(Math.round(inside/getResources().getDisplayMetrics().density),getResources().getConfiguration().fontScale,getChildCount());childWidth=Math.max(1,(inside-gap*(columns-1))/columns);heights.clear();int height=getPaddingTop()+getPaddingBottom();for(int i=0;i<getChildCount();i++){View child=getChildAt(i);child.measure(MeasureSpec.makeMeasureSpec(childWidth,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(0,MeasureSpec.UNSPECIFIED));int row=i/columns;if(row==heights.size())heights.add(0);heights.set(row,Math.max(heights.get(row),child.getMeasuredHeight()));}for(int i=0;i<heights.size();i++)height+=heights.get(i)+(i==0?0:gap);setMeasuredDimension(resolveSize(width,widthSpec),resolveSize(height,heightSpec));}
  @Override protected void onLayout(boolean changed,int l,int t,int r,int b){int top=getPaddingTop();for(int i=0;i<getChildCount();i++){int row=i/columns,column=i%columns;if(column==0&&row>0)top+=heights.get(row-1)+gap;int left=getPaddingLeft()+column*(childWidth+gap);getChildAt(i).layout(left,top,left+childWidth,top+heights.get(row));}}
 }
