 private void chooseFeature(){java.util.List<OneCatalog.Feature> choices=new ArrayList<>();for(OneCatalog.Feature value:OneCatalog.all()){if(compareMode&&(OneCatalog.inputs(value,true).length==0||OneModels.list(this,value.id,group).size()<2))continue;if(selectedInput!=null&&(!OneCatalog.accepts(value,inputMedia,compareMode)||inputFeatures.length>0&&!Arrays.asList(inputFeatures).contains(value.id)))continue;choices.add(value);}String[] labels=new String[choices.size()];for(int i=0;i<labels.length;i++)labels[i]=choices.get(i).title;new AlertDialog.Builder(this).setTitle(selectedInput==null?"기능 선택":"같은 자료로 기능 선택").setItems(labels,(dialog,index)->{OneCatalog.Feature next=choices.get(index);feature=next.id;media=selectedInput!=null?inputMedia:OneCatalog.inputs(next,compareMode)[0];render();}).setNegativeButton("닫기",null).show();}
